const { hashPassword, verifyPassword, signToken } = require("../auth");
const { getLastIDs } = require("../middleware/students_middleware");
const { insertUser } = require("../middleware/users_middleware");
const { db, query, crypto, moment, fs, leadingZero } = require("../models/models");

const addStudents = async (req, res) => {
  try {
    const {
      name,
      email,
      nationality,
      birth_date,
      identity_type,
      identity_number,
      identity_valid_data,
      address,
      contact,
    } = req.body;

    // 🔸 Validação básica
    if (!name || !email) {
      return res
        .status(400)
        .json({ error: "Campos obrigatórios ausentes: name ou email." });
    }

    // 🔹 Verificar se já existe estudante com o mesmo nome e email
    const existing = await query(
      "SELECT id FROM students WHERE name = ? OR email = ? LIMIT 1",
      [name, email]
    );

    if (existing.length > 0) {
      return res.status(409).json({
        error: "Estudante já existe com o mesmo nome ou email.",
      });
    }

    // 🔹 Data atual
    const currentYear = new Date().getFullYear();
    const currentMonth = String(new Date().getMonth() + 1).padStart(2, "0");

    // 🔹 Buscar último student_number
    const lastStudent = await query(
      "SELECT student_number FROM students ORDER BY id DESC LIMIT 1"
    );

    let newSeq = 1;

    if (lastStudent && lastStudent.student_number) {
      const lastNumber = lastStudent.student_number.toString();
      const lastYear = parseInt(lastNumber.slice(4, 8)); // extrai o ano do meio (ex: 0001202510 → 2025)
      const lastSeq = parseInt(lastNumber.slice(0, 4)); // primeiros 4 dígitos = sequência

      newSeq = lastYear === currentYear ? lastSeq + 1 : 1;
    }

    // 🔹 Formato final: sequência (4 dígitos) + ano + mês → ex: 0001202510
    const student_number = parseInt(
      `${leadingZero(newSeq, 3)}${currentMonth}${currentYear}`
    );

    // 🔹 Inserir estudante
    const result = await query(
      `INSERT INTO students (
        student_number,
        name,
        email,
        nationality,
        birth_date,
        identity_type,
        identity_number,
        identity_valid_data,
        address,
        contact
      ) VALUES (?,?,?,?,?,?,?,?,?,?)`,
      [
        student_number,
        name,
        email,
        nationality,
        birth_date,
        identity_type,
        identity_number,
        identity_valid_data,
        address,
        contact
      ]
    );

    if (!result.insertId) {
      return res.status(500).json({ error: "Falha ao criar estudante." });
    }

    // 🔹 Criar password automática: primeiro nome + _ + ID
    const firstName = name.split(" ")[0]?.toLowerCase() || "user";
    const password = `${firstName}_${String(result.insertId).padStart(4, "0")}`;

    // 🔹 Criar usuário vinculado ao estudante
    const row = await insertUser(name, email, password, "student");

    if (!row) {
      return res
        .status(500)
        .json({ error: "Falha ao criar usuário para o estudante." });
    }

    // 🔹 Buscar e retornar estudante completo
    const student = await query("SELECT * FROM students WHERE id = ?", [
      result.insertId,
    ]);

    res.status(201).json({
      message: "Estudante criado com sucesso!",
      student,
      credentials: { email, password }, // opcional
    });
  } catch (err) {
    console.error("Erro ao adicionar estudante:", err);
    res.status(500).json({ error: "Erro interno do servidor." });
  }
};


const getStudents = async (req, res) => {
  try {
    const {
      page = 1,
      limit = 40,
      name = "",
      sort = "recent",
      status = "",
      loadedIds = []
    } = req.body;

    const parsedLimit = Math.max(parseInt(limit) || 40, 1);
    const parsedPage = Math.max(parseInt(page) || 1, 1);
    const offset = (parsedPage - 1) * parsedLimit;

    let where = " WHERE 1=1 ";
    const queryParams = [];

    // 🔎 Filtro por nome
    if (name) {
      where += " AND s.name LIKE ? ";
      queryParams.push(`%${name}%`);
    }

    // 🔎 Filtro por status
    if (status) {
      where += " AND e.status = ? ";
      queryParams.push(status);
    }

    // 🔎 Excluir IDs já carregados
    if (Array.isArray(loadedIds) && loadedIds.length > 0) {
      where += ` AND s.id NOT IN (${loadedIds.map(() => "?").join(",")}) `;
      queryParams.push(...loadedIds);
    }

    // 🔀 Ordenação
    let orderBy = " ORDER BY s.id DESC ";
    switch (sort) {
      case "oldest":
        orderBy = " ORDER BY s.id ASC ";
        break;
      case "name_asc":
        orderBy = " ORDER BY s.name ASC ";
        break;
      case "name_desc":
        orderBy = " ORDER BY s.name DESC ";
        break;
    }

    // 🔹 Query principal (SEM GROUP_CONCAT)
    const sql = `
      SELECT 
        s.id,
        s.student_number,
        s.name,
        s.email,
        s.birth_date,
        s.address,
        s.nationality,
        s.identity_type,
        s.identity_number,
        s.identity_valid_data,
        s.contact,
        c.title AS course,
        e.status AS enrollment_status

      FROM students s
      LEFT JOIN enrollments e ON e.student_id = s.id
      LEFT JOIN classes cl ON cl.id = e.class_id
      LEFT JOIN courses c ON c.id = cl.course_id

      ${where}
      ${orderBy}
      LIMIT ? OFFSET ?
    `;

    const rows = await query(sql, [
      ...queryParams,
      parsedLimit,
      offset
    ]);

    // 🔹 Agrupar cursos no backend
    const grouped = {};

    rows.forEach(row => {
      if (!grouped[row.id]) {
        grouped[row.id] = {
          id: row.id,
          student_number: row.student_number,
          name: row.name,
          email: row.email,
          birth_date: row.birth_date,
          address: row.address,
          nationality: row.nationality,
          identity_type: row.identity_type,
          identity_number: row.identity_number,
          identity_valid_data: row.identity_valid_data,
          contact: row.contact,
          courses: []
        };
      }

      if (row.course) {
        grouped[row.id].courses.push({
          title: row.course,
          status: row.enrollment_status || "active"
        });
      }
    });

    const students = Object.values(grouped);

    // 🔹 Total com os mesmos filtros
    const countSql = `
      SELECT COUNT(DISTINCT s.id) AS total
      FROM students s
      LEFT JOIN enrollments e ON e.student_id = s.id
      ${where}
    `;

    const [{ total }] = await query(countSql, queryParams);

    return res.status(200).json({
      page: parsedPage,
      limit: parsedLimit,
      total,
      totalPages: Math.ceil(total / parsedLimit),
      students
    });

  } catch (err) {
    console.error("Erro ao listar estudantes:", err);
    return res.status(500).json({ error: "internal_error" });
  }
};


const updateStudent = async (req, res) => {
  try {
    const { id } = req.params;
    const {
      name,
      email,
      nationality,
      birth_date,
      identity_type,
      identity_number,
      identity_valid_data,
      address,
      contact,
    } = req.body;

    console.log(name,
      email,
      nationality,
      birth_date,
      identity_type,
      identity_number,
      identity_valid_data,
      address,
      contact)

    if (!id) return res.status(400).json({ error: "ID do estudante é obrigatório." });

    // 🔹 Verifica se o estudante existe
    const existing = await query("SELECT * FROM students WHERE id = ?", [id]);
    if (!existing.length)
      return res.status(404).json({ error: "Estudante não encontrado." });

    // 🔹 Verifica duplicação de nome/email (excluindo o próprio estudante)
    const duplicate = await query(
      "SELECT id FROM students WHERE (email = ? OR name = ?) AND id != ?",
      [email, name, id]
    );
    if (duplicate.length)
      return res.status(400).json({ error: "Já existe um estudante com esse nome ou email." });

    // 🔹 Atualiza apenas campos enviados
    const updatedFields = {
      name,
      email,
      nationality,
      birth_date,
      identity_type,
      identity_number,
      identity_valid_data,
      address,
      contact,
    };

    // Remove chaves com undefined
    Object.keys(updatedFields).forEach(
      (k) => updatedFields[k] === undefined && delete updatedFields[k]
    );

    if (Object.keys(updatedFields).length === 0)
      return res.status(400).json({ error: "Nenhum campo para atualizar." });

    await query("UPDATE students SET ? WHERE id = ?", [updatedFields, id]);

    const updated = await query("SELECT * FROM students WHERE id = ?", [id]);

    res.json({
      message: "Estudante atualizado com sucesso!",
      student: updated,
    });
  } catch (err) {
    console.error("Erro ao atualizar estudante:", err);
    res.status(500).json({ error: "Erro interno do servidor." });
  }
};



const deleteStudent = async (req, res) => {
  try {
    const { id } = req.params;

    if (!id) return res.status(400).json({ error: "ID do estudante é obrigatório." });

    // 🔹 Verifica se o estudante existe
    const rows = await query("SELECT * FROM students WHERE id = ?", [id]);
    if (!rows.length)
      return res.status(404).json({ error: "Estudante não encontrado." });

    const data = rows[0];

    // 🔹 Remove estudante (e opcionalmente o usuário vinculado)

    // Se quiser remover o usuário vinculado (caso exista)
    await db.query("DELETE FROM users WHERE role = 'student' AND email = ?", [data?.email]);
    await db.query("DELETE FROM enrollments WHERE student_id = ?", [data?.id]);
    await db.query("DELETE FROM students WHERE id = ?", [data?.id]);

    res.json({
      message: "Estudante removido com sucesso!",
      deletedId: id,
    });
  } catch (err) {
    console.error("Erro ao excluir estudante:", err);
    res.status(500).json({ error: "Erro interno do servidor." });
  }
};


module.exports = { addStudents, getStudents, updateStudent, deleteStudent };
